def comps(g):
    lab,n=ndimage.label(np.array(g), structure=np.ones((3,3)))
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        out.append(np.array(g)[ys.min():ys.max()+1,xs.min():xs.max()+1])
    return out
def vsym(s): return (s==s[:,::-1]).all()
def hsym(s): return (s==s[::-1,:]).all()
